// Bitmask DP - Recursion
// At each (mask, pos): try every unvisited item as next
// TIME: O(n!), SPACE: O(n)

// MINIMIZE (TSP - Traveling Salesman)
public int tsp(int curr, int mask, int n, int[][] dist) {
    if (mask == (1 << n) - 1) return dist[curr][0];

    int result = Integer.MAX_VALUE;
    for (int next = 0; next < n; next++) {
        if ((mask & (1 << next)) == 0) {
            int cost = dist[curr][next] + tsp(next, mask | (1 << next), n, dist);
            result = Math.min(result, cost);
        }
    }
    return result;
}

// COUNT (Beautiful Arrangement)
public int countArrangement(int pos, int mask, int n) {
    if (pos > n) return 1;

    int count = 0;
    for (int num = 1; num <= n; num++) {
        if ((mask & (1 << num)) == 0 &&
            (num % pos == 0 || pos % num == 0)) {
            count += countArrangement(pos + 1, mask | (1 << num), n);
        }
    }
    return count;
}

// FEASIBILITY (Partition to K Equal Sum Subsets)
public boolean canPartition(int mask, int currSum, int k, int target, int[] nums) {
    if (k == 0) return mask == (1 << nums.length) - 1;
    if (currSum == target) return canPartition(mask, 0, k - 1, target, nums);

    for (int i = 0; i < nums.length; i++) {
        if ((mask & (1 << i)) == 0 && currSum + nums[i] <= target) {
            if (canPartition(mask | (1 << i), currSum + nums[i], k, target, nums)) {
                return true;
            }
        }
    }
    return false;
}

