// Bitmask DP - Memoization
// TIME: O(2^n * n^2), SPACE: O(2^n * n)

// MINIMIZE (TSP)
public int tsp(int curr, int mask, int n, int[][] dist, int[][] memo) {
    if (mask == (1 << n) - 1) return dist[curr][0];
    if (memo[curr][mask] != -1) return memo[curr][mask];

    int result = Integer.MAX_VALUE;
    for (int next = 0; next < n; next++) {
        if ((mask & (1 << next)) == 0) {
            int cost = dist[curr][next] + tsp(next, mask | (1 << next), n, dist, memo);
            result = Math.min(result, cost);
        }
    }
    memo[curr][mask] = result;
    return result;
}

// COUNT (Beautiful Arrangement)
public int countArrangement(int mask, int n, int[] memo) {
    int pos = Integer.bitCount(mask) + 1;
    if (pos > n) return 1;
    if (memo[mask] != -1) return memo[mask];

    int count = 0;
    for (int num = 1; num <= n; num++) {
        if ((mask & (1 << num)) == 0 &&
            (num % pos == 0 || pos % num == 0)) {
            count += countArrangement(mask | (1 << num), n, memo);
        }
    }
    memo[mask] = count;
    return count;
}

// FEASIBILITY (Partition to K Equal Sum Subsets)
public boolean canPartition(int mask, int currSum, int k, int target, 
                            int[] nums, Map<Long, Boolean> memo) {
    if (k == 0) return mask == (1 << nums.length) - 1;
    if (currSum == target) return canPartition(mask, 0, k - 1, target, nums, memo);

    long key = ((long) mask << 20) | currSum;
    if (memo.containsKey(key)) return memo.get(key);

    for (int i = 0; i < nums.length; i++) {
        if ((mask & (1 << i)) == 0 && currSum + nums[i] <= target) {
            if (canPartition(mask | (1 << i), currSum + nums[i], k, target, nums, memo)) {
                memo.put(key, true);
                return true;
            }
        }
    }
    memo.put(key, false);
    return false;
}

