// Bitmask DP - Tabulation
// Process masks in increasing order (smaller masks computed first)
// TIME: O(2^n * n^2), SPACE: O(2^n * n)

// MINIMIZE (TSP)
public int tsp(int[][] dist) {
    int n = dist.length;
    int[][] dp = new int[1 << n][n];
    for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE);
    dp[1][0] = 0;  // Start at city 0

    for (int mask = 1; mask < (1 << n); mask++) {
        for (int curr = 0; curr < n; curr++) {
            if (dp[mask][curr] == Integer.MAX_VALUE) continue;

            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0) {
                    int newMask = mask | (1 << next);
                    dp[newMask][next] = Math.min(
                        dp[newMask][next],
                        dp[mask][curr] + dist[curr][next]
                    );
                }
            }
        }
    }

    int fullMask = (1 << n) - 1;
    int result = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (dp[fullMask][i] != Integer.MAX_VALUE) {
            result = Math.min(result, dp[fullMask][i] + dist[i][0]);
        }
    }
    return result;
}

// COUNT (Beautiful Arrangement)
public int countArrangement(int n) {
    int[] dp = new int[1 << n];
    dp[0] = 1;

    for (int mask = 0; mask < (1 << n); mask++) {
        int pos = Integer.bitCount(mask) + 1;
        if (pos > n) continue;

        for (int num = 1; num <= n; num++) {
            if ((mask & (1 << (num - 1))) == 0 &&
                (num % pos == 0 || pos % num == 0)) {
                dp[mask | (1 << (num - 1))] += dp[mask];
            }
        }
    }
    return dp[(1 << n) - 1];
}

