// Bitmask DP - Advanced Techniques
// When position doesn't matter, use O(2^n) instead of O(2^n * n)

// O(2^n) space when pos is implicit
public int countArrangement(int n) {
    int[] dp = new int[1 << n];
    dp[0] = 1;

    for (int mask = 0; mask < (1 << n); mask++) {
        int pos = Integer.bitCount(mask) + 1;

        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                int num = i + 1;
                if (num % pos == 0 || pos % num == 0) {
                    dp[mask | (1 << i)] += dp[mask];
                }
            }
        }
    }
    return dp[(1 << n) - 1];
}

// SUBSET ENUMERATION - Iterate all subsets of a mask
// Time: O(2^popcount(mask))
public void enumerateSubsets(int mask) {
    int subset = mask;
    while (subset > 0) {
        // process subset
        subset = (subset - 1) & mask;
    }
    // don't forget subset = 0
}

// MEET-IN-THE-MIDDLE for larger n
// Split into two halves, process each with 2^(n/2)
public boolean subsetSumMitM(int[] nums, int target) {
    int n = nums.length;
    int mid = n / 2;

    Set<Integer> firstHalf = new HashSet<>();
    for (int mask = 0; mask < (1 << mid); mask++) {
        int sum = 0;
        for (int i = 0; i < mid; i++) {
            if ((mask & (1 << i)) != 0) sum += nums[i];
        }
        firstHalf.add(sum);
    }

    int remaining = n - mid;
    for (int mask = 0; mask < (1 << remaining); mask++) {
        int sum = 0;
        for (int i = 0; i < remaining; i++) {
            if ((mask & (1 << i)) != 0) sum += nums[mid + i];
        }
        if (firstHalf.contains(target - sum)) return true;
    }
    return false;
}

