// TSP - Recursion
// TIME: O(n! * n), SPACE: O(n)

public int minCost(int[][] dist) {
    int n = dist.length;
    return solve(0, 1, n, dist);
}

private int solve(int curr, int mask, int n, int[][] dist) {
    if (mask == (1 << n) - 1) {
        return dist[curr][0];
    }

    int result = Integer.MAX_VALUE;
    for (int next = 0; next < n; next++) {
        if ((mask & (1 << next)) == 0) {
            int cost = dist[curr][next] + solve(next, mask | (1 << next), n, dist);
            result = Math.min(result, cost);
        }
    }
    return result;
}

