// TSP - Memoization
// TIME: O(2^n * n^2), SPACE: O(2^n * n)

public int minCost(int[][] dist) {
    int n = dist.length;
    int[][] memo = new int[n][1 << n];
    for (int[] row : memo) Arrays.fill(row, -1);
    return solve(0, 1, n, dist, memo);
}

private int solve(int curr, int mask, int n, int[][] dist, int[][] memo) {
    if (mask == (1 << n) - 1) {
        return dist[curr][0];
    }
    if (memo[curr][mask] != -1) return memo[curr][mask];

    int result = Integer.MAX_VALUE;
    for (int next = 0; next < n; next++) {
        if ((mask & (1 << next)) == 0) {
            int cost = dist[curr][next] + solve(next, mask | (1 << next), n, dist, memo);
            result = Math.min(result, cost);
        }
    }

    memo[curr][mask] = result;
    return result;
}

