// TSP - Memoization
// TIME: O(2^n * n^2), SPACE: O(2^n * n)

function minCost(dist) {
    const n = dist.length;
    const memo = {};

    function solve(curr, mask) {
        if (mask === (1 << n) - 1) {
            return dist[curr][0];
        }

        const key = curr + ',' + mask;
        if (key in memo) return memo[key];

        let result = Infinity;
        for (let next = 0; next < n; next++) {
            if (!(mask & (1 << next))) {
                const cost = dist[curr][next] + solve(next, mask | (1 << next));
                result = Math.min(result, cost);
            }
        }

        memo[key] = result;
        return result;
    }

    return solve(0, 1);
}

